<div class="gamification-admin-head"><div><a href="<?php echo url('admin/tournaments') ?>"><?php echo icon('fas fa-arrow-left') ?> <?php echo $this->lang('Tournaments') ?></a><h2><?php echo utf8_htmlentities($tournament['title']) ?></h2></div><?php echo $this->button_create('admin/tournaments/participants/'.$tournament['tournament_id'].'/add', (string)$this->lang('Add participant')) ?></div><div class="table-responsive"><table class="table"><thead><tr><th><?php echo $this->lang('Participant') ?></th><th><?php echo $this->lang('Seed') ?></th><th><?php echo $this->lang('Group') ?></th><th><?php echo $this->lang('Actions') ?></th></tr></thead><tbody><?php foreach ($participants as $row): ?><tr><td><?php echo utf8_htmlentities($row['team_title'] ?: $row['name']) ?></td><td><?php echo utf8_htmlentities($row['seed_number'] ?? '') ?></td><td><?php echo utf8_htmlentities($row['group_name']) ?></td><td><?php echo $this->button_update('admin/tournaments/participants/edit/'.$row['participant_id']) ?><?php echo $this->button_delete('admin/tournaments/participants/delete/'.$row['participant_id']) ?></td></tr><?php endforeach ?></tbody></table></div>
